import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Installation","description":"Install Firewall-Plus on a Pterodactyl panel via Blueprint or the standalone installer, then deploy the node daemon to every Wings host.","frontmatter":{"title":"Installation","description":"Install Firewall-Plus on a Pterodactyl panel via Blueprint or the standalone installer, then deploy the node daemon to every Wings host."},"headers":[],"relativePath":"firewall-plus/getting-started/installation.md","filePath":"firewall-plus/getting-started/installation.md","lastUpdated":1785501747000}'),n={name:"firewall-plus/getting-started/installation.md"};function l(o,s,r,h,p,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Firewall-Plus has two install halves:</p><ol><li><strong>Panel extension</strong> — Blueprint addon (recommended) or standalone installer.</li><li><strong>Node daemon</strong> — the <code>firewall-plus</code> Fastify service on <strong>every</strong> Wings host.</li></ol><p>Both halves must be installed and on compatible versions for applies to work.</p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p><strong>Panel:</strong></p><ul><li>Pterodactyl Panel 1.x with PHP 8.2+ and the standard panel extensions</li><li><a href="https://blueprint.zip" target="_blank" rel="noreferrer">Blueprint</a> framework (Blueprint path only)</li><li>Working <strong>scheduler cron</strong>: <code>* * * * * php /var/www/pterodactyl/artisan schedule:run</code></li><li>Working <strong>queue worker</strong> (<code>pteroq</code> systemd service or <code>php artisan queue:work</code>) — applies are queued jobs; without a worker nothing reaches the node</li></ul><p><strong>Each Wings node:</strong></p><ul><li>Linux host with <code>iptables</code> and <code>ipset</code> installed (nft-backed <code>iptables-nft</code> is auto-detected and preferred)</li><li>Node.js 18+ (installed by the node installer if missing)</li><li>Root/systemd for the <code>firewall-plus</code> service (needs <code>CAP_NET_ADMIN</code>)</li></ul><hr><h2 id="panel-blueprint-install-recommended" tabindex="-1">Panel: Blueprint Install (recommended) <a class="header-anchor" href="#panel-blueprint-install-recommended" aria-label="Permalink to &quot;Panel: Blueprint Install (recommended)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylfirewallplus-v1.2.6.blueprint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>Verify the extension is registered:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus</span></span></code></pre></div><p>You should see the <code>firewall-plus:*</code> commands. The admin sidebar gains a <strong>Firewall</strong> section, and each server&#39;s settings gain a <strong>Firewall</strong> tab.</p><h2 id="panel-standalone-install-no-blueprint" tabindex="-1">Panel: Standalone Install (no Blueprint) <a class="header-anchor" href="#panel-standalone-install-no-blueprint" aria-label="Permalink to &quot;Panel: Standalone Install (no Blueprint)&quot;">​</a></h2><p>Download the release and use the <code>standalone/</code> folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactyl-firewall-plus/standalone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # from /var/www/pterodactyl</span></span></code></pre></div><p>To remove it later:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">PHP extensions under Blueprint&#39;s sanitized environment</p><p>Blueprint runs its install steps in a sanitized shell. If your panel&#39;s PHP CLI relies on extensions loaded via per-user ini paths (common with <code>php-fpm</code> + custom pools), the install can fail with missing-extension errors even though <code>php -m</code> looks fine in your normal shell. Run the install as the same user and environment Blueprint uses, and check <code>php -m</code> under <code>sudo -u www-data</code> (or your web user) if something is reported missing.</p></div><hr><h2 id="node-installation" tabindex="-1">Node Installation <a class="header-anchor" href="#node-installation" aria-label="Permalink to &quot;Node Installation&quot;">​</a></h2><p>Run on <strong>every</strong> Wings host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://fw-install.pingless.org/node/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre></div><p>The installer:</p><ul><li>Drops the service into <code>/opt/firewall-plus</code></li><li>Writes <code>/etc/firewall-plus/config.json</code> and generates a 64-hex bearer token at <code>/etc/firewall-plus/token</code> (chmod <code>600</code>)</li><li>Installs and starts the hardened <code>firewall-plus</code> systemd unit</li><li>Prints the token once — you paste it into the panel when adding the node</li></ul><p>Verify locally on the node:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8472/api/v1/health</span></span></code></pre></div><p>Healthy output includes <code>meta.version</code> and <code>data.input_jump_style</code> (<code>per-port-dport-v2</code> on current builds):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input_jump_style&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;per-port-dport-v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;meta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Then in the panel: <strong>Admin → Firewall → Nodes → Add Node</strong> — pick the Wings node, set the FQDN (plain HTTP, not HTTPS — see troubleshooting), and paste the bearer token. The panel stores only a bcrypt hash plus the encrypted token.</p><h3 id="upgrading-the-node-daemon" tabindex="-1">Upgrading the node daemon <a class="header-anchor" href="#upgrading-the-node-daemon" aria-label="Permalink to &quot;Upgrading the node daemon&quot;">​</a></h3><p>The node daemon is <strong>not</strong> updated by panel/Blueprint reinstalls. On each Wings host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://fw-install.pingless.org/node/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # re-run = upgrade</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8472/api/v1/health</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{version: .meta.version, input_jump_style: .data.input_jump_style}&#39;</span></span></code></pre></div><p>The service logs <code>nodeServiceVersion</code> at startup, and <strong>Admin → Firewall → Nodes</strong> shows each node&#39;s reported version and health.</p><hr><h2 id="post-install-verification" tabindex="-1">Post-Install Verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-Install Verification&quot;">​</a></h2><ol><li><strong>Scheduler + queue:</strong> confirm <code>php artisan schedule:run</code> runs every minute via cron and <code>systemctl status pteroq</code> (or your queue worker) is active.</li><li><strong>Node online:</strong> Admin → Firewall → Nodes shows the node <strong>ONLINE</strong> (a node is marked offline after 2 failed health checks by default).</li><li><strong>Enable on a test server:</strong> Server → Settings → Firewall → enable <strong>Firewall-Plus for this server</strong>, accept the ToS, add a rule, and click <strong>Apply firewall</strong>.</li><li><strong>Check the node:</strong> <code>iptables -L FWP-&lt;serverId&gt; -n -v</code> and <code>ipset list fwp-wl-&lt;serverId&gt;</code> should show your rules.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Watch the apply job land on the node</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="an-unexpected-error-was-encountered-when-applying" tabindex="-1">&quot;An unexpected error was encountered…&quot; when applying <a class="header-anchor" href="#an-unexpected-error-was-encountered-when-applying" aria-label="Permalink to &quot;&quot;An unexpected error was encountered…&quot; when applying&quot;">​</a></h3><p>Pterodactyl&#39;s API handler hides real exceptions when <code>APP_DEBUG=false</code>. Check <code>storage/logs/laravel.log</code> at the same timestamp (search <code>firewall_plus.apply</code>). Typical causes: <strong>migrations not run</strong> (<code>php artisan migrate --force</code>), a <strong>queue worker not running</strong> (apply returns <code>202</code> and sits queued), or a non-JSON-encodable rule value.</p><h3 id="service-provider-not-registered" tabindex="-1">Service provider not registered <a class="header-anchor" href="#service-provider-not-registered" aria-label="Permalink to &quot;Service provider not registered&quot;">​</a></h3><p>If routes 404 or <code>php artisan list firewall-plus</code> shows nothing, <code>FirewallPlusServiceProvider</code> was not registered. On Blueprint, reinstall the extension; on standalone, re-run <code>install.sh</code> and confirm the provider line survived in <code>config/app.php</code> (or the panel&#39;s provider bootstrap), then <code>php artisan config:clear</code>.</p><h3 id="node-version-skew-—-multiport-needs-p-tcp" tabindex="-1">Node version skew — <code>multiport needs -p tcp</code> <a class="header-anchor" href="#node-version-skew-—-multiport-needs-p-tcp" aria-label="Permalink to &quot;Node version skew — \`multiport needs -p tcp\`&quot;">​</a></h3><p>This error means the <strong>Wings host is running an old node daemon</strong>, not a panel bug. Upgrade the node (see above) and restart <code>firewall-plus</code>. Confirm <code>input_jump_style</code> reports <code>per-port-dport-v2</code>.</p><h3 id="openssl-wrong-version-number-on-node-health" tabindex="-1">OpenSSL &quot;wrong version number&quot; on node health <a class="header-anchor" href="#openssl-wrong-version-number-on-node-health" aria-label="Permalink to &quot;OpenSSL &quot;wrong version number&quot; on node health&quot;">​</a></h3><p>The panel is speaking <strong>HTTPS</strong> to the daemon, which serves <strong>plain HTTP</strong> on <code>:8472</code>. Wings&#39; daemon URL scheme must not be copied to Firewall-Plus. Fix: <strong>Admin → Firewall → Nodes → Edit FQDN</strong> → answer <strong>Cancel</strong> on &quot;Use HTTPS?&quot;, or set <code>FIREWALL_PLUS_NODE_USE_SSL=false</code> in <code>.env</code> for newly added nodes. Existing node rows keep their stored <code>use_ssl</code> flag until edited.</p><h3 id="applies-time-out-with-empty-stderr-docker-on-the-same-host" tabindex="-1">Applies time out with empty stderr (Docker on the same host) <a class="header-anchor" href="#applies-time-out-with-empty-stderr-docker-on-the-same-host" aria-label="Permalink to &quot;Applies time out with empty stderr (Docker on the same host)&quot;">​</a></h3><p>If <code>docker info</code> reports <code>Firewall Backend: iptables</code>, Docker and Firewall-Plus contend for the same <code>iptables-nft-restore</code> serialization. Symptoms: <code>FWP iptables-restore starting</code> then silence until <code>ERR_COMMAND_FAILED</code> (~120s), and a stuck <code>iptables-nft-restore -w 5 --noflush --table filter</code> in <code>ps</code>. Mitigations, in order of safety:</p><ol><li>Avoid mass <code>docker compose up</code> / image pulls during applies; retry when the host is quiet.</li><li>Raise the restore timeout in the systemd unit: <code>Environment=FWP_IPTABLES_RESTORE_TIMEOUT_MS=300000</code> (clamped 10s–600s). Symptom relief only.</li><li>Prove it: stop Docker briefly in a maintenance window and run one apply.</li><li>Last resort (expert): Docker daemon <code>&quot;iptables&quot;: false</code> — breaks default bridge NAT unless you replace it. Do not do this in production without a networking plan.</li></ol><p>Use <code>iptables-nft-save -t filter | grep FWP</code> to inspect rules when legacy <code>iptables</code> prints <em>Incompatible with this kernel</em>.</p><h3 id="node-refuses-to-start-with-an-empty-whitelist" tabindex="-1">Node refuses to start with an empty whitelist <a class="header-anchor" href="#node-refuses-to-start-with-an-empty-whitelist" aria-label="Permalink to &quot;Node refuses to start with an empty whitelist&quot;">​</a></h3><p>By design: a daemon bound to a non-loopback address with an empty <code>allowedIps</code> refuses to start — any reachable host could otherwise drive your iptables. Either bind to <code>127.0.0.1</code>, add your panel&#39;s IP/CIDR to <code>allowedIps</code>, or set <code>allowEmptyWhitelist: true</code> only if you know exactly why.</p><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>Follow the full rollback runbook — in short:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Flush all managed chains on online nodes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:emergency-flush</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --confirm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. On each node</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/firewall-plus/uninstall.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # or node-service/uninstall.sh from the repo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Panel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylfirewallplus</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Blueprint</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or: sudo bash standalone/uninstall.sh      # standalone</span></span></code></pre></div><p>Verify nodes are clean: <code>iptables -L -n | grep FWP</code> and <code>ipset list | grep fwp</code> should return nothing. Dropping the firewall tables is a separate, destructive step — see the project&#39;s <code>docs/ROLLBACK.md</code>.</p>`,62)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
